path=Path(r'E:/type10-7/github_publish/CVS-RFFI-repo/experiments/phase1_spectral_prior_gate/spectral_prior_source.py');tree=ast.parse(path.read_text(encoding='utf8'));node=next(x for x in tree.body if isinstance(x,ast.FunctionDef) and x.name=='make_prior');env={'torch':torch,'F':F};exec(compile(ast.fix_missing_locations(ast.Module(body=[node],type_ignores=[])),str(path),'exec'),env);torch.manual_seed(258);base=torch.randn(256,dtype=torch.complex64);factors=torch.polar(torch.linspace(.7,1.3,16),torch.linspace(-2,2,16));bank=torch.cat((factors[:,None]*base[None,:],torch.randn(16,256,dtype=torch.complex64)),0);center=bank[:,64:-64];power=center.abs().square().sum(1).clamp_min(1e-12);unit=center/power.sqrt()[:,None];gains=torch.tensor([1+0j,.5+.7j,-1.2+.2j],dtype=torch.complex64);z=gains[:,None]*base[None,:];anchor=torch.stack((z.real,z.imag),1);out=env['make_prior'](anchor,bank,power,unit);assert torch.allclose(out,anchor,atol=3e-5,rtol=3e-5),(out-anchor).abs().max();blank=torch.zeros_like(anchor);assert torch.isfinite(env['make_prior'](blank,bank,power,unit)).all();print('PASS known complex scaling and zero input, maximum error',float((out-anchor).abs().max()))
